/*
 * A026605  [3->null]-transform of three-symbol Thue-Morse A026600.
 * https://oeis.org/A026605
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the n‑th non‑3 term of the 3‑symbol Thue‑Morse sequence
 *            generated by the morphism 1 → 123, 2 → 231, 3 → 312.
 *            Equivalently, a(n) = g(k) where g(k) = (sum of the base‑3 digits
 *            of k) mod 3 + 1 and k is the smallest integer for which a(n)
 *            appears among the non‑3 symbols of g. The function sea...
 * Range:     u8 n <= 90, u16 n <= 90, u32 n <= 90, u64 n <= 90, u128 n <= 90,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    idx_t count = 0;    /* number of non‑3 symbols seen so far */
    idx_t i = 0;        /* current position in the 3‑symbol Thue‑Morse word */

    while (1) {
        /* compute (sum of base‑3 digits of i) mod 3 */
        idx_t x = i;
        unsigned int sum_mod3 = 0;   /* 0,1,2 only */

        while (x > 0) {
            sum_mod3 += x % 3;      /* add current digit */
            if (sum_mod3 >= 3)
                sum_mod3 -= 3;       /* keep modulo 3 */
            x /= 3;
        }

        seq_t value = (seq_t)(sum_mod3 + 1);  /* 1→1, 2→2, 3→3 */

        if (value != 3) {                 /* non‑3 symbol */
            ++count;
            if (count == n)
                return value;
        }

        ++i;  /* next position */
    }
}
